guided_steps.solution:
age = 25

# if文を使って判定してください
if age >= 20:
    print("成人です")
else:
    print("未成年です")

age = 15

# if, elif, elseを使って判定してください
if age >= 20:
    print("成人")
elif age >= 13:
    print("中高生")
else:
    print("子供")

challenges.solution:
age = 7

print("年齢: " + str(age) + "歳")

if age == 6:
    print("小学1年生")
elif age == 7:
    print("小学2年生")
elif age == 8:
    print("小学3年生")
else:
    print("対象外")
